INSERT INTO permissions(code) SELECT unnest(ARRAY['meeting.create','meeting.view','meeting.manage','savings.view','savings.record','social_fund.view','social_fund.record','fine.view','fine.record','financial.reverse']) ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code IN ('SUPER_ADMIN','PROJECT_ADMIN','STATE_COORDINATOR','FACILITATOR') AND p.code IN ('meeting.create','meeting.view','meeting.manage','savings.view','savings.record','social_fund.view','social_fund.record','fine.view','fine.record','financial.reverse') ON CONFLICT DO NOTHING;
